    choices: ["A) Electric vehicles produce no emissions and are therefore completely clean.","B) Though EVs produce no direct emissions during operation, the manufacturing process — particularly battery production — involves energy use and mining with their own environmental costs, complicating claims of complete environmental neutrality.","C) Battery mining is the biggest environmental problem today.","D) EVs are bad for the environment."],
