    answer: 'D',
    explanation: 'Slope of ℓ: rearrange 3x−4y=12 → y=(3/4)x−3, so slope=3/4. Perpendicular slope = −4/3. Line m through (6,−1): y+1 = (−4/3)(x−6) → y = (−4/3)x+8−1 = (−4/3)x+7. x-intercept (set y=0): 0 = −(4/3)x+7 → x = 21/4.',
