        id: 'RW264',
    section: 'reading_writing',
    topic: 'Standard English Conventions',
    subtopic: 'Verb Tense',
    difficulty: 'medium',
    points: 1,
    passage: 'By the time the rescue team arrived at the summit, the stranded climbers _______ there for more than eighteen hours.',
    text: 'Which choice correctly completes the sentence?',
    choices: ['A) waited', 'B) have waited', 'C) had been waiting', 'D) were waiting'],
    answer: 'C',
    explanation: '"By the time... arrived" establishes a past reference point. An action that was ongoing up to that past point requires past perfect progressive: "had been waiting." Simple past "waited" doesn\'t convey the ongoing duration. "Have waited" is present perfect (wrong time frame). "Were waiting" doesn\'t convey the duration up to the arrival point as precisely.',
    tags: ['verb tense', 'past perfect progressive', 'conventions']
