    passage: 'A student is writing a paper about the health effects of ultra-processed foods. The student wants to introduce the topic by establishing its public health significance. Which choice best accomplishes that goal?\n\n[Note 1] Ultra-processed foods now account for over 60% of calories consumed by Americans.\n[Note 2] Ultra-processed foods contain emulsifiers, artificial flavors, and preservatives not found in home cooking.\n[Note 3] A 2019 clinical trial found that participants assigned to an ultra-processed diet consumed 500 more calories per day and gained an average of 2 pounds over two weeks.\n[Note 4] The ultra-processed food industry spent $14 billion on advertising in the United States in 2022.',
