    explanation: 'B combines Notes 1 and 3 to establish both prevalence (60% of calories) and harmful effect (+500 cal/day), directly arguing for public health significance. A only describes ingredients. C is about advertising spending, not health. D provides evidence but lacks the "public health significance" framing — it\'s one data point, not a scope-setting statement.',
