    difficulty: 'hard',
    points: 1,
    passage: 'Contrary to widespread belief, the Great Wall of China is not visible from space with the naked eye. The wall is roughly 5–9 meters wide — comparable in width to a highway — and human vision at orbital altitude cannot resolve objects less than about 10 kilometers across. Photographs purporting to show the wall from orbit have consistently turned out to show rivers or other geological features.',
