    choices: ['A) The Great Wall of China was built to be visible over long distances.', 'B) The claim that the Great Wall is visible from space is factually incorrect.', 'C) Modern cameras in orbit are unable to photograph narrow structures like the Great Wall.', 'D) Geological features are often mistaken for man-made structures in aerial photography.'],
